import pennylane as qml

dev = qml.device("default.qubit", wires=3)


@qml.qnode(dev)
def circuit():
    qml.CNOT(wires=[0, 1])
    qml.CZ(wires=[1, 0])
    qml.CNOT(wires=[2, 0])
    qml.CZ(wires=[1, 2])
    # PennyLane lists wire 0 first in a state; Qiskit lists qubit 0 last. The circuit is the same.
    return qml.state()
